            rt = routes[i]
            if not rt:
                continue
            for pos in range(len(rt)):
                c = rt[pos]
                dc = demands[c]
                prev = depot if pos == 0 else rt[pos - 1]
                nxt = depot if pos == len(rt) - 1 else rt[pos + 1]
                remove_delta = dist(prev, nxt) - dist(prev, c) - dist(c, nxt)
                for j in range(len(routes)):
                    if i == j:
                        continue
                    rj = routes[j]
                    if route_loads[j] + dc > capacity:
                        continue
                    m = len(rj)
                    for ins in range(m + 1):
                        a = depot if ins == 0 else rj[ins - 1]
                        b = depot if ins == m else rj[ins]
                        add_delta = dist(a, c) + dist(c, b) - dist(a, b)
                        gain = remove_delta - add_delta
                        if gain > 1e-12:
                            rt.pop(pos)
                            route_loads[i] -= dc
                            rj.insert(ins, c)
                            route_loads[j] += dc
                            route_costs[i] = route_cost(rt)
                            route_costs[j] = route_cost(rj)
                            improved = True
                            break
                    if improved:
                        break
                if improved:
                    break
            if improved:
                break

        if improved:
            continue

        # Swap between routes
        for i in range(len(routes)):
            rt = routes[i]
            for pi in range(len(rt)):
                a = rt[pi]
                da = demands[a]
                pa = depot if pi == 0 else rt[pi - 1]
                na = depot if pi == len(rt) - 1 else rt[pi + 1]
                rem_a = dist(pa, na) - dist(pa, a) - dist(a, na)
                for j in range(i + 1, len(routes)):
                    rj = routes[j]
                    for pj in range(len(rj)):
                        b = rj[pj]
                        db = demands[b]
                        if route_loads[i] - da + db > capacity:
                            continue
                        if route_loads[j] - db + da > capacity:
                            continue
                        pb = depot if pj == 0 else rj[pj - 1]
                        nb = depot if pj == len(rj) - 1 else rj[pj + 1]
                        rem_b = dist(pb, nb) - dist(pb, b) - dist(b, nb)
                        add_a = dist(pa, b) + dist(b, na) - dist(pa, na)
                        add_b = dist(pb, a) + dist(a, nb) - dist(pb, nb)
                        gain = (rem_a + rem_b) - (add_a + add_b)
                        if gain > 1e-12:
                            rt[pi], rj[pj] = b, a
                            route_costs[i] = route_cost(rt)
                            route_costs[j] = route_cost(rj)
                            improved = True
                            break
                    if improved:
                        break
                if improved:
                    break
            if improved:
                break

    # Final cleanup: remove empty routes and ensure all customers exactly once.
    final_routes = []
    seen = [0] * n
    for rt in routes:
        if rt:
            final_routes.append(rt)
            for c in rt:
                if 0 <= c < n:
                    seen[c] += 1

    # If any customer missing due to unexpected input, append them greedily.
    missing = [i for i in customers if seen[i] == 0]
    for c in missing:
        dc = demands[c]
        best = None
        best_inc = None
        best_pos = None
        for ri, rt in enumerate(final_routes):
            load = 0
            for x in rt:
                load += demands[x]
            if load + dc > capacity:
                continue
            m = len(rt)
            for pos in range(m + 1):
                prev = depot if pos == 0 else rt[pos - 1]
                nxt = depot if pos == m else rt[pos]
                inc = dist(prev, c) + dist(c, nxt) - dist(prev, nxt)
                if best_inc is None or inc < best_inc:
                    best = ri
                    best_inc = inc
                    best_pos = pos
        if best is None:
            final_routes.append([c])
        else:
            final_routes[best].insert(best_pos, c)

    return final_routes
